/**
 * lib/server-mode.js — Server-side IRU mode (institutional vs consumer).
 *
 * Reads api/build-mode.json (generated by scripts/set-build-mode.mjs at
 * build time; committed default is 'consumer'). The institutional branch
 * resolves to 'institutional' from the Vercel branch ref, so its Preview
 * deployment is organization-authorized without any dashboard env var.
 *
 * SERVER ONLY. Do not import from client code (src/) — this uses node:fs.
 * Fail-closed: any read/parse failure returns 'consumer', so the
 * consumer paywall gates stay enforced. An institutional deployment
 * that fails to resolve its mode simply behaves like the consumer app
 * (gates on) rather than silently ungating delivery.
 */
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

let cached = null;

export function serverBuildMode() {
  if (cached) return cached;
  // Explicit override (tests and local dev only): IRU_SERVER_MODE set to
  // 'institutional' forces institutional mode without touching the
  // committed build-mode.json. Unset in production, so the fail-closed
  // file-based resolution below is unchanged there.
  if (process.env.IRU_SERVER_MODE === 'institutional') {
    cached = 'institutional';
    return cached;
  }
  try {
    const here = dirname(fileURLToPath(import.meta.url));
    const raw = readFileSync(join(here, '..', 'build-mode.json'), 'utf8');
    const parsed = JSON.parse(raw);
    cached = parsed && parsed.mode === 'institutional' ? 'institutional' : 'consumer';
  } catch {
    cached = 'consumer';
  }
  return cached;
}

// Test hook: drop the cached mode so a test can switch modes within one
// process by changing IRU_SERVER_MODE. Never used in production code.
export function resetServerModeCache() {
  cached = null;
}

export function isInstitutionalServer() {
  return serverBuildMode() === 'institutional';
}
